                        .map(|&token_id| PositionLogprobs {
                            entries: (0..=top_k as u32)
                                .map(|rank| TokenLogprob {
                                    token_id: token_id.wrapping_add(rank) % 150_000,
                                    logprob: -(rank as f32),
                                    rank: rank + 1,
                                })
                                .collect(),
                        })
                        .collect(),
                });
            }
            out
        })
        .collect()
}

fn run(tokenizer: &DynTokenizer, all: &[Vec<GenerateOutput>], detokenize: bool) -> f64 {
    let start = Instant::now();
    for outputs in all {
        let events = block_on(
            decoded_text_event_stream(
                "bench".into(),
                Arc::clone(tokenizer),
                stream::iter(outputs.clone().into_iter().map(Ok)),
                TextDecodeOptions {
                    detokenize,
                    ..Default::default()
                },
                true,
            )
            .collect::<Vec<_>>(),
        );
        assert!(events.iter().all(Result::is_ok));
    }
    start.elapsed().as_secs_f64()
}

